class Solution:
    def maximumProduct(self, nums: List[int]) -> int:
        # brute-force: 3 loops to find top 3 max nums
        # return a * b * c -> n^3

        # Sort nlogn then return product
        nums.sort()
        return max(nums[-1] * nums[-2] * nums[-3], nums[-1] * nums[0] * nums[1])
